import {RISK_AGE_ROWS,SURVEY_2024,RISK_TYPE_NAMES} from './risk-statistics-data.js';
export const RISK_SOURCE={name:`${SURVEY_2024.source} · ${SURVEY_2024.title}`,year:SURVEY_2024.year,url:SURVEY_2024.url};
const idx=m=>Number(m.slice(0,4))*12+Number(m.slice(5))-1;
export const statisticalAge=s=>s.startAge+Math.floor((idx(s.month)-idx(s.start))/12);
export function annualToMonthly(p){if(!Number.isFinite(p)||p<0||p>1)throw Error('연간 비율은 0~1이어야 합니다.');return p===1?1:-Math.expm1(Math.log1p(-p)/12);}
export function riskRow(year,age,type='fraud'){return RISK_AGE_ROWS.find(r=>r.year===year&&r.type===type&&age>=r.minAge&&(r.maxAge===null||age<=r.maxAge))||null;}
export function riskEvidence(s,type=s.pending?.type==='fraud'?'fraud':s.pending?.type==='scam'?'fraud':null){const years=statisticalAge(s),year=Number(s.month.slice(0,4)),row=type?riskRow(year,years,type):null;
 if(!row)return {status:'unavailable',age:years,year,annualProbability:null,monthlyProbability:null,source:RISK_SOURCE,message:`${years}세 · ${year}년의 이 사건 피해 확률은 자료 미연결입니다. 가상 연습 사건은 한국인의 실제 피해 비율이 아닙니다.`};
 const p=row.annualPercent/100;return {status:'verified-age-band',age:years,year,ageBand:row.ageBand,annualProbability:p,monthlyProbability:annualToMonthly(p),source:RISK_SOURCE,row,message:`${year}년 조사 대상 ${row.ageBand}의 연간 ${RISK_TYPE_NAMES[type]} 피해 경험 비율은 ${row.annualPercent.toFixed(1)}%입니다. ${years}세만의 비율이나 전체 한국인의 비율은 아닙니다.`};
}
export function evidenceForEvent(event){const row=RISK_AGE_ROWS.find(r=>r.id===event.statisticId);if(!row)return {status:'unavailable',source:RISK_SOURCE,message:'이 사건의 통계 기록을 확인할 수 없습니다.'};return {status:'verified-age-band',source:RISK_SOURCE,row,annualProbability:row.annualPercent/100,monthlyProbability:annualToMonthly(row.annualPercent/100),message:`${row.year}년 조사 대상 ${row.ageBand}의 연간 사기 피해 경험 비율 ${row.annualPercent.toFixed(1)}%. 단일 나이의 비율이나 제안 노출률이 아닙니다.`};}
export function riskEvidenceHTML(s,e){const applied=s.pending?.type==='fraud'&&s.pending?.statisticId;const r=applied?evidenceForEvent(s.pending):riskEvidence(s);return `${applied?`<p class="statistic-caption">${r.row.year}년 · 조사 대상 ${e(r.row.ageBand)} · 연간 사기 피해 경험 ${r.row.annualPercent.toFixed(1)}%</p>`:'<p class="statistic-caption">실제 발생률 미연결 · 가상 연습 사건</p>'}<details class="risk-evidence"><summary>이 사건은 실제로 얼마나 발생할까요?</summary><p>${e(r.message)}</p>${r.status==='verified-age-band'?`<p>대상: ${e(SURVEY_2024.population)}.<br>관찰 기간: ${e(SURVEY_2024.period)}.<br>조사: ${e(SURVEY_2024.surveyPeriod)} · 사후 재현용 자료.<br>${applied?'게임 월 추첨값 '+(r.monthlyProbability*100).toFixed(4)+'% · 어려움 배수 없음.':'제안 노출률과 피해 경험률은 달라 이 수치를 제안 이벤트의 등장 확률로 사용하지 않습니다.'}</p><p>월 독립·동일 위험을 가정한 환산입니다. 한 해 첫 경험만 추첨하며 연령대 변화·중도 시작·게임 조건에 따라 체감 빈도가 달라집니다. 손실액·회복 효과는 별도의 게임 가정입니다.</p>`:'<p>자료가 없는 연도는 최신 조사로 소급하지 않습니다. 피해자 중 연령 구성비와 신고 사건 수는 개인의 피해 확률이 아닙니다.</p>'}<a href="${r.source.url}" target="_blank" rel="noopener noreferrer">${e(r.source.name)} · 공식 수치 확인 ↗</a></details>`;}
export function renderRiskCoverage(e,s){return `<details class="finance-help"><summary>연령별 위험 통계 · 연결 범위</summary>${s&&!s.rules?.statistics?'<p>현재 기록은 이전 게임 규칙을 유지합니다. 통계 발생 모형은 새 삶에서 적용됩니다.</p>':''}<p>2024년 사기 피해 경험률만 발생 계산에 연결했습니다. 나머지 연도와 사고·고용·분쟁의 실제 확률은 미연결입니다. 2024년 대인절도·폭력·재산범죄 수치는 참고 자료이며 발생 계산에는 사용하지 않습니다. 재산범죄에 포함된 유형들을 더해 확률을 중복 계산하지 않습니다.</p><div class="study-table-scroll"><table><thead><tr><th>조사 연령대</th><th>사기 · 연간 경험률</th><th>월 환산 · 게임 가정</th></tr></thead><tbody>${RISK_AGE_ROWS.filter(r=>r.type==='fraud').map(r=>`<tr><th>${e(r.ageBand)}</th><td>${r.annualPercent.toFixed(1)}%</td><td>${(annualToMonthly(r.annualPercent/100)*100).toFixed(4)}%</td></tr>`).join('')}</tbody></table></div><p>전체 조사 ${SURVEY_2024.samplePeople.toLocaleString('ko-KR')}명 · ${SURVEY_2024.sampleHouseholds.toLocaleString('ko-KR')}가구. ${e(SURVEY_2024.limitation)}</p><a href="${RISK_SOURCE.url}" target="_blank" rel="noopener noreferrer">${e(RISK_SOURCE.name)} ↗</a></details>`;}

export function deterministicRiskRoll(seed,month,type){let h=2166136261;for(const c of `${seed}|${month}|${type}`)h=Math.imul(h^c.charCodeAt(0),16777619);h^=h>>>16;h=Math.imul(h,0x85ebca6b);h^=h>>>13;h=Math.imul(h,0xc2b2ae35);h^=h>>>16;return (h>>>0)/4294967296;}
